mapper.select:
SELECT agentType AS "agentType",
       caseKindCd AS "caseKindCd",
       COUNT(*) AS "cnt"
  FROM (
        SELECT DISTINCT 'L' AS agentType, su.SUIT_ID AS suitId, su.CASE_KIND_CD AS caseKindCd
          FROM LAW_SUIT su
         WHERE su.DEL_YN = 'N'
           AND su.RSLT_KIND_CD = #{processingCd}
           AND EXISTS (SELECT 1 FROM LAW_SUIT_LAWYER l WHERE l.SUIT_ID = su.SUIT_ID)
         AND su.FR_DT >= #{fromDate} 
         AND su.FR_DT <= #{toDate} 
        UNION ALL
        SELECT DISTINCT 'G' AS agentType, su.SUIT_ID AS suitId, su.CASE_KIND_CD AS caseKindCd
          FROM LAW_SUIT su
         WHERE su.DEL_YN = 'N'
           AND su.RSLT_KIND_CD = #{processingCd}
           AND EXISTS (SELECT 1 FROM LAW_SUIT_STAFF s WHERE s.SUIT_ID = su.SUIT_ID)
           AND NOT EXISTS (SELECT 1 FROM LAW_SUIT_LAWYER l WHERE l.SUIT_ID = su.SUIT_ID)
         AND su.FR_DT >= #{fromDate} 
         AND su.FR_DT <= #{toDate} 
       ) t
 GROUP BY agentType, caseKindCd

SELECT su.SUIT_ID AS "suitId", su.CASE_NO AS "caseNo", su.CASE_NM AS "caseNm", ld.LOCATION AS "location", ld.JIBUN AS "jibun" FROM LAW_SUIT_LAND ld JOIN LAW_SUIT su ON ld.SUIT_ID = su.SUIT_ID WHERE su.DEL_YN = 'N' AND ( (su.FR_DT IS NOT NULL AND su.FR_DT BETWEEN #{fromDate} AND #{toDate}) OR (su.FR_DT IS NULL AND su.DCSN_DT BETWEEN #{fromDate} AND #{toDate}) )
AND su.RSLT_KIND_CD IN #{r}
AND ( ld.LOCATION IS NOT NULL OR ld.JIBUN IS NOT NULL ) ORDER BY su.SUIT_ID
